def can_read(actor, owner):
    return actor["id"] == owner["id"] and actor["tenant"] == owner["tenant"]
import unittest
from permissions import can_read
class Tests(unittest.TestCase):
    def test_owner(self): self.assertTrue(can_read({"id":"a","tenant":"x"}, {"id":"a","tenant":"x"}))
    def test_other(self): self.assertFalse(can_read({"id":"b","tenant":"x"}, {"id":"a","tenant":"x"}))

    def test_same_id_in_different_tenant(self):
        self.assertFalse(can_read(
            {"id": "a", "tenant": "y"},
            {"id": "a", "tenant": "x"},
        ))

    def test_different_id_and_tenant(self):
        self.assertFalse(can_read(
            {"id": "b", "tenant": "y"},
            {"id": "a", "tenant": "x"},
        ))
